import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

fused_gemm_activation_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_gemm_activation_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int batch_size,
    const int in_features,
    const int out_features)
{
    int idx = blockDim.x * blockIdx.x + threadIdx.x;
    int total = batch_size * out_features;
    if (idx < total) {
        int row = idx / out_features;
        int col = idx % out_features;

        float val = 0.0f;
        // GEMM
        for (int k = 0; k < in_features; k++) {
            val += input[row * in_features + k] * weight[col * in_features + k];
        }
        // Add bias
        val += bias[col];

        // HardTanh
        if (val < -1.0f) val = -1.0f;
        else if (val > 1.0f) val = 1.0f;

        // Mish
        float sp = logf(1.0f + expf(val));
        float t = tanhf(sp);
        val = val * t;

        output[idx] = val;
    }
}

torch::Tensor fused_gemm_activation_cuda(
    torch::Tensor x,
    torch::Tensor w,
    torch::Tensor b)
{
    auto batch_size = x.size(0);
    auto in_features = x.size(1);
    auto out_features = w.size(0);

    auto out = torch::zeros({batch_size, out_features}, x.options());

    int total = batch_size * out_features;
    const int block_size = 256;
    int grid_size = (total + block_size - 1) / block_size;

    fused_gemm_activation_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        w.data_ptr<float>(),
        b.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size,
        in_features,
        out_features
    );
    return out;
}
"""

fused_gemm_activation_cpp_source = r"""
torch::Tensor fused_gemm_activation_cuda(torch::Tensor x,
                                         torch::Tensor w,
                                         torch::Tensor b);
"""

fused_gemm_activation = load_inline(
    name="fused_gemm_activation",
    cpp_sources=[fused_gemm_activation_cpp_source],
    cuda_sources=[fused_gemm_activation_source],
    functions=["fused_gemm_activation_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    A model that fuses GEMM, extra bias addition, HardTanh, and Mish into a custom CUDA kernel,
    followed by GroupNorm.
    """
    def __init__(self, in_features, out_features, bias_shape, num_groups):
        super(ModelNew, self).__init__()
        # Original structures for initialization
        self.gemm = nn.Linear(in_features, out_features)
        self.extra_bias = nn.Parameter(torch.randn(bias_shape))

        # Create fused parameters (weight + fused bias)
        with torch.no_grad():
            self.weight = nn.Parameter(self.gemm.weight.clone())
            self.fused_bias = nn.Parameter(self.gemm.bias.clone() + self.extra_bias.clone())

        self.groupnorm = nn.GroupNorm(num_groups=num_groups, num_channels=out_features)

    def forward(self, x):
        # Fused GEMM + bias + HardTanh + Mish
        x = fused_gemm_activation.fused_gemm_activation_cuda(x, self.weight, self.fused_bias)
        # GroupNorm
        x = self.groupnorm(x)
        return x

def get_inputs():
    batch_size = 128
    in_features = 512
    return [torch.randn(batch_size, in_features).cuda()]

def get_init_inputs():
    in_features = 512
    out_features = 1024
    bias_shape = (out_features,)
    num_groups = 32
    return [in_features, out_features, bias_shape, num_groups]
